+    v.add(field, "required");
+    return undefined;
+  }
+  if (typeof x !== "string") {
+    v.add(field, "invalid");
+    return undefined;
+  }
+  const s = o.trim ? x.trim() : x;
+  const n = charLen(s);
+  const min = o.min ?? 0;
+  if (n < min) {
+    v.add(field, n === 0 ? "too_short" : "too_short");
+    return undefined;
+  }
+  if (n > o.max) {
+    v.add(field, "too_long");
+    return undefined;
+  }
+  return s;
