+
+export function optEnum<T extends string>(
+  v: Validator,
+  body: Record<string, unknown>,
+  field: string,
+  values: readonly T[],
+  required = false,
+): T | undefined {
+  if (!(field in body) || body[field] === null) {
+    if (required || field in body) v.add(field, "required");
+    return undefined;
+  }
+  const x = body[field];
+  if (typeof x !== "string" || !(values as readonly string[]).includes(x)) {
+    v.add(field, "invalid");
+    return undefined;
+  }
+  return x as T;
+}
